package br.com.brindespro;
import br.com.brindespro.catalog.*;import br.com.brindespro.pricing.*;import br.com.brindespro.admin.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") class PricingIntegrationTest { @Autowired PricingService pricing;@Autowired ProductRepository products;@Autowired KitRepository kits;
 private PricingService.Request request(Product p,int quantity,String position,String deadline){return new PricingService.Request(p.id,p.variants.iterator().next().id,quantity,"Laser",position,deadline,null,null,null,null);}
 @Test void baseTierAndBoundary(){Product p=products.findBySlugAndActiveTrue("garrafa-termica-inox-500ml").orElseThrow();assertEquals(new BigDecimal("18.90"),pricing.calculate(request(p,100,"Frente","Padrão")).unitPrice());assertEquals(new BigDecimal("1890.00"),pricing.calculate(request(p,100,"Frente","Padrão")).total());assertNotEquals(pricing.calculate(request(p,49,"Frente","Padrão")).unitPrice(),pricing.calculate(request(p,50,"Frente","Padrão")).unitPrice());assertDoesNotThrow(()->pricing.calculate(request(p,1500,"Frente","Padrão")));}
 @Test void percentagesAddToBaseThenRoundUnit(){Product p=products.findBySlugAndActiveTrue("garrafa-termica-inox-500ml").orElseThrow();var result=pricing.calculate(request(p,100,"Frente e verso","Urgente"));assertEquals(new BigDecimal("26.46"),result.unitPrice());assertEquals(new BigDecimal("2646.00"),result.total());assertEquals(new BigDecimal("756.00"),result.surcharge());}
 @Test void rejectsBelowMinimum(){Product p=products.findBySlugAndActiveTrue("garrafa-termica-inox-500ml").orElseThrow();assertThrows(IllegalArgumentException.class,()->pricing.calculate(request(p,4,"Frente","Padrão")));}
 @Test void kitDiscountAppliesAfterSurcharges(){Product p=products.findBySlugAndActiveTrue("garrafa-termica-inox-500ml").orElseThrow();Kit kit=new Kit("Kit Teste");kit.discountPercent=new BigDecimal("0.10");kit.items.add(new KitItem(kit,p,1));kits.saveAndFlush(kit);var line=new PricingService.Request(p.id,p.variants.iterator().next().id,100,"Laser","Frente e verso","Urgente",kit.id,null,null,null);assertEquals(new BigDecimal("23.81"),pricing.calculate(line).unitPrice());assertEquals(new BigDecimal("2381.00"),pricing.calculate(line).total());}
}
